scenario.ru:
// Родитель создаёт rows заново на каждом рендере — что увидит memo?
function FilterPanel({ items, query }) {
  const filtered = items.filter((i) => i.name.includes(query));
  return (
    <List
      rows={filtered.map(decorate)}   // свежий массив + свежие объекты каждый рендер
    />
  );
}

const Row = React.memo(function Row({ row }) {
  return <li>{row.label}</li>;
});
